func (q *Queries) SamePartyAmong(ctx context.Context, arg SamePartyAmongParams) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, samePartyAmong, arg.ActorID, arg.Ids)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []uuid.UUID
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const setActionReview = `-- name: SetActionReview :execrows
UPDATE action
SET review_state = $2, reviewed_by_member_id = $3, reviewed_at = $4
WHERE id = $1 AND review_state IN ('pending', 'escalated')
`

type SetActionReviewParams struct {
	ID                 uuid.UUID
	ReviewState        string
	ReviewedByMemberID *uuid.UUID
	ReviewedAt         *time.Time
}

func (q *Queries) SetActionReview(ctx context.Context, arg SetActionReviewParams) (int64, error) {
	result, err := q.db.Exec(ctx, setActionReview,
		arg.ID,
		arg.ReviewState,
		arg.ReviewedByMemberID,
		arg.ReviewedAt,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
